// Every uploaded file is checked: a real JPG, PNG or WEBP (read from the file's first bytes, so a renamed PDF is
// refused) of MAX_MB at most. Up to MAX_FILES good files are queued, one item each; the refused ones are listed.
const MAX_MB = 5;
const MAX_FILES = 20;
const item = $input.first();
const keys = Object.keys(item.binary || {});
const batchId = $now.setZone("Africa/Casablanca").toFormat("yyyy-MM-dd_HH-mm-ss") + "_" + $execution.id;
const accepted = [];
const refused = [];
for (const key of keys) {
    const file = item.binary[key];
    const name = file.fileName || key;
    const bytes = await this.helpers.getBinaryDataBuffer(0, key);
    const head = bytes.subarray(0, 12);
    const ascii = (from, to) => head.subarray(from, to).toString("latin1");
    let format = "";
    if (head[0] === 0xff && head[1] === 0xd8 && head[2] === 0xff) format = "jpg";
    else if (head[0] === 0x89 && ascii(1, 4) === "PNG") format = "png";
    else if (ascii(0, 4) === "RIFF" && ascii(8, 12) === "WEBP") format = "webp";
    let reason = "";
    if (!format) reason = "not a JPG, PNG or WEBP image";
    else if (bytes.length > MAX_MB * 1024 * 1024) reason = (bytes.length / 1024 / 1024).toFixed(1) + " MB, the maximum is " + MAX_MB + " MB";
    else if (bytes.length < 100) reason = "empty or damaged";
    else if (accepted.length >= MAX_FILES) reason = "more than " + MAX_FILES + " files in one upload";
    if (reason) { refused.push({ name, reason }); continue; }
    const queueName = batchId + "_" + String(accepted.length + 1).padStart(2, "0") + "." + format;
    const mimeType = { jpg: "image/jpeg", png: "image/png", webp: "image/webp" }[format];
    accepted.push({ json: { batchId, queueName, originalName: name }, binary: { reference: { ...file, mimeType, fileName: queueName, fileExtension: format } } });
}
if (!accepted.length) return [{ json: { none: true, batchId, refused } }];
return accepted.map((a) => ({ json: { ...a.json, refused }, binary: a.binary }));

// <batchId>_batch.json: what the worker paints and what it made of each reference
const accepted = $('form: Check uploads').all().map((item) => item.json);
const manifest = {
    batchId: accepted[0].batchId,
    submittedAt: $now.setZone("Africa/Casablanca").toISO(),
    files: accepted.map((a) => ({ queueName: a.queueName, originalName: a.originalName, status: "queued", tries: 0 })),
    refused: accepted[0].refused,
};
const fileName = manifest.batchId + "_batch.json";
return [{
    json: { fileName },
    binary: { data: { data: Buffer.from(JSON.stringify(manifest, null, 2)).toString("base64"), mimeType: "application/json", fileName } },
}];

// The page shown after sending: what was queued and what was refused
const checked = $('form: Check uploads').all().map((item) => item.json);
const first = checked[0];
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const queued = first.none ? [] : checked.map((c) => c.originalName);
const refused = first.refused || [];
const folderUrl = "https://drive.google.com/drive/folders/" + $('form: Settings').first().json.agentFolderId;
let html = "<h2>" + queued.length + " artwork" + (queued.length > 1 ? "s" : "") + " queued</h2>"
    + "<p>They are painted one after another, about 2 minutes each, and appear in Drive as Artwork Agent/1xxx. You can close this page.</p>"
    + "<ul>" + queued.map((n) => "<li>" + esc(n) + "</li>").join("") + "</ul>";
if (refused.length) html += "<h3>" + refused.length + " refused</h3><ul>" + refused.map((r) => "<li>" + esc(r.name) + ": " + esc(r.reason) + "</li>").join("") + "</ul>";
html += '<p><a href="' + folderUrl + '" target="_blank">Open Artwork Agent in Drive</a></p>';
return [{ json: { html: '<div style="font-family:system-ui,sans-serif;max-width:640px;margin:0 auto;text-align:left">' + html + "</div>" } }];

// The page shown after sending: what was queued and what was refused
const checked = $('form: Check uploads').all().map((item) => item.json);
const first = checked[0];
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const queued = first.none ? [] : checked.map((c) => c.originalName);
const refused = first.refused || [];
const folderUrl = "https://drive.google.com/drive/folders/" + $('form: Settings').first().json.agentFolderId;
let html = "<h2>Nothing was queued</h2><p>None of the files can be used:</p>"
    + "<ul>" + refused.map((r) => "<li>" + esc(r.name) + ": " + esc(r.reason) + "</li>").join("") + "</ul>"
    + '<p><a href="javascript:history.back()">Try again</a></p>';
return [{ json: { html: '<div style="font-family:system-ui,sans-serif;max-width:640px;margin:0 auto;text-align:left">' + html + "</div>" } }];

// Queued, refused, and the whole queue: how many references wait (earlier batches first) and roughly how long
const checked = $('form: Check uploads').all().map((item) => item.json);
const first = checked[0];
const refused = first.refused || [];
const queued = checked.map((c) => c.originalName);
const waiting = ($input.first().json.files || []).filter((f) => new RegExp("^\\d{4}-\\d{2}-\\d{2}_\\d{2}-\\d{2}-\\d{2}_\\d{2}\\.(jpg|png|webp)$").test(f.name));
const ahead = waiting.filter((f) => f.name.slice(0, 19) < first.batchId).length;
const lines = ["Artwork Agent: " + queued.length + " image" + (queued.length === 1 ? "" : "s") + " queued for painting (batch " + first.batchId + ")"];
for (const name of queued) lines.push("- " + name);
if (refused.length) {
    lines.push("", refused.length + " refused:");
    for (const r of refused) lines.push("- " + r.name + ": " + r.reason);
}
lines.push("", "Queue: " + waiting.length + " image" + (waiting.length === 1 ? "" : "s") + " waiting" + (ahead ? ", " + ahead + " from earlier uploads first" : "") + ". About " + (waiting.length * 2) + " min to paint them all, one after another.");
lines.push("Each one gets its folder Artwork Agent/1xxx; you get the painted artwork here.");
return [{ json: { text: lines.join("\n") } }];

const refused = $('form: Check uploads').first().json.refused || [];
const lines = ["Artwork Agent: nothing queued, none of the " + refused.length + " file" + (refused.length === 1 ? "" : "s") + " can be used:"];
for (const r of refused) lines.push("- " + r.name + ": " + r.reason);
return [{ json: { text: lines.join("\n") } }];

// Another run holds a fresh lock (refreshed within its stale time, kept in its description)
const OWN = Number($('worker: Settings').first().json.lockStaleMinutes);
const staleMs = (l) => { const m = /staleMinutes=(\d+)/.exec(l.description || ""); return (m ? Number(m[1]) : OWN) * 60000; };
const isFresh = (l) => Date.now() - new Date(l.modifiedTime || l.createdTime).getTime() < staleMs(l);
const locks = $input.first().json.files || [];
const fresh = locks.filter(isFresh);
const stale = locks.filter((l) => !fresh.includes(l)).map((l) => l.id);
return [{ json: { free: fresh.length === 0, fresh: fresh.length, stale } }];

// Two runs can create a lock at the same moment: the oldest fresh lock wins, the other run steps back
const mine = $('worker: Create lock').last().json;
const OWN = Number($('worker: Settings').first().json.lockStaleMinutes);
const staleMs = (l) => { const m = /staleMinutes=(\d+)/.exec(l.description || ""); return (m ? Number(m[1]) : OWN) * 60000; };
const isFresh = (l) => Date.now() - new Date(l.modifiedTime || l.createdTime).getTime() < staleMs(l);
const fresh = ($input.first().json.files || [])
    .filter((l) => l.id === mine.id || isFresh(l))
    .sort((a, b) => (a.createdTime < b.createdTime ? -1 : a.createdTime > b.createdTime ? 1 : a.id < b.id ? -1 : 1));
return [{ json: { won: fresh.length > 0 && fresh[0].id === mine.id, lockId: mine.id } }];

const files = $input.first().json.files || [];
const images = files.filter((f) => /^.+_[0-9]{2}[.](jpg|png|webp)$/.test(f.name)).sort((a,b) => a.name.localeCompare(b.name));
if (!images.length) return [{ json: { none: true } }];
const image = images[0];
const batchId = image.name.split("_").slice(0, -1).join("_");
const manifest = files.find((f) => f.name === batchId + "_batch.json");
return [{ json: { none: false, fileId: image.id, queueName: image.name, extension: image.name.split(".").pop(), batchId, manifestId: manifest ? manifest.id : "", remaining: images.length - 1 } }];

// One more try for this reference: after maxTries runs that stopped midway, it is set aside as failed.
// A reference whose result is already recorded (the run stopped after painting it, before moving it) is not painted
// again: this run only finishes its move.
const settings = $('worker: Settings').first().json;
const next = $('worker: Next reference').first().json;
const manifest = next.manifestId && $('worker: Download manifest').isExecuted ? $('worker: Download manifest').first().json : null;
let tries = 1;
let originalName = next.queueName;
let finished = null;
if (manifest && Array.isArray(manifest.files)) {
    const entry = manifest.files.find((e) => e.queueName === next.queueName);
    if (entry) {
        originalName = entry.originalName || originalName;
        if (entry.status === "done" || entry.status === "failed") {
            finished = { status: entry.status, folder: entry.folder || "", folderId: entry.folderId || "", referenceName: entry.referenceName || "", reason: entry.reason || "" };
            tries = Number(entry.tries) || 1;
        } else {
            entry.tries = (Number(entry.tries) || 0) + 1;
            tries = entry.tries;
        }
    }
}
const out = { json: { tries, giveUp: !finished && tries > Number(settings.maxTries), originalName, manifest, hasManifest: !!manifest && !finished, finished } };
if (manifest) out.binary = { manifest: { data: Buffer.from(JSON.stringify(manifest, null, 2)).toString("base64"), mimeType: "application/json", fileName: next.batchId + "_batch.json" } };
return [out];

// the result from the manifest: the reference is only moved out of the queue
const f = $('worker: Start attempt').first().json.finished;
return [{ json: { ...f, recovered: true } }];

// The queued image becomes the "reference" file, and the run gets its date+time stamp
const settings = $('worker: Settings').first().json;
const next = $('worker: Next reference').first().json;
const file = $input.first().binary && $input.first().binary.reference;
if (!file) throw new Error("Could not download the queued reference " + next.queueName);
const stamp = $now.setZone(settings.timezone).toFormat("yyyy-MM-dd_HH-mm-ss");
const referenceName = stamp + "_ref." + next.extension;
return [{
    json: {
        stamp,
        referenceName,
        artworkName: stamp + "_art.png",
        paletteName: stamp + "_palette.json",
    },
    binary: { reference: { ...file, fileName: referenceName } },
}];

// A fixed prompt: the model sees the reference itself, so no scene description is needed. The artwork keeps the
// reference's shape: landscape (5:4) for a reference wider than tall, portrait (4:5) otherwise (a square one too).
const settings = $('worker: Settings').first().json;
const size = $('worker: Measure reference').first().json;
if (!size.width || !size.height) throw new Error("Could not read the reference's size: " + JSON.stringify(size).slice(0, 200));
const setting = String(settings.orientation || "auto").toLowerCase();
const orientation = setting === "portrait" || setting === "landscape" ? setting : size.width > size.height ? "landscape" : "portrait";
const [a, b] = String(settings.imageSize).split("x").map(Number);
const imageSize = orientation === "landscape" ? Math.max(a, b) + "x" + Math.min(a, b) : Math.min(a, b) + "x" + Math.max(a, b);
const frame = orientation === "landscape"
    ? "The output is a horizontal canvas painting in a 5:4 ratio (30 x 24 cm), wider than tall."
    : "The output is a vertical canvas painting in a 4:5 ratio (24 x 30 cm), taller than wide.";
const imagePrompt = [
    "Repaint this image as a highly detailed digital painting in flat cel-shaded color, like a fine gouache or screen-print illustration made for a paint-by-numbers canvas.",
    frame + " Recompose the scene to fit this frame naturally: keep every subject whole and in proportion, extend the surrounding scenery where the frame needs more room, and never stretch, squash or distort anything.",
    "Paint only the artwork itself: ignore any white or grey background, wall, shadow, picture frame or canvas edge around it in the reference. A decorative border that is part of the design itself (a patterned zellij or rug border, an ornamental band) is kept.",
    "Keep everything from the artwork exactly: the same subjects, likeness, expressions, poses, objects and background, with realistic proportions.",
    // references with signs or posters were failing the checker 3 times out of 3: the painting leaves their writing out.
    // License plates, vehicle emblems, badges and logos on objects stay as they are (the 48-color snap blurs them anyway)
    "The one exception: leave out the writing in the scene. Every sign, shop name, poster, label, sticker, calligraphy, inscription, signature and watermark is painted without any letter or word: a sign becomes a blank board in its own color, calligraphy or an inscription a simple ornamental band with no letters. License plates, vehicle emblems, badges and logos on objects may stay as they are.",
    "Keep the original colors of the image.",
    "Each area is painted in flat solid tones with crisp, clean, smooth edges, and shading is built from distinct flat tone steps.",
    "Preserve every fine detail: facial features, eyes, lips, fingers, hair strands, clothing folds, individual leaves, reflections, architecture.",
    "Smooth high-resolution shapes, not pixel art, no pixelated blocks, no gradients, no blur, no texture, no grain, no brush strokes, no outlines. Geometric tile patterns (zellij, mosaics, star patterns) in the reference are kept as crisp flat shapes.",
    "The painting fills the entire image edge to edge. Do not add anything to the image: no color bar, no swatches, no palette, no legend, no labels, no text, no numbers, no added border, no margin.",
].join("\n");
return [{ json: { imagePrompt, orientation, imageSize, referenceWidth: size.width, referenceHeight: size.height }, binary: $('worker: Prepare').first().binary }];

const r = $input.first().json;
const text = JSON.stringify(r.error || r).slice(0, 3000);
const message = String((r.error && (r.error.description || r.error.message)) || "OpenAI returned no image").slice(0, 400);
const refused = /moderation_blocked|safety system|content_policy|safety_violation/i.test(text);
return [{ json: { refused, service: !refused && /insufficient_quota|exceeded your current quota|billing|invalid_api_key|incorrect api key|account is not active|unauthori[sz]ed|forbidden|\b40[13]\b|\b429\b|rate.?limit|too many requests|ECONNREFUSED|ENOTFOUND|EAI_AGAIN|credentials? not found|could not be decrypted/i.test(text), message } }];

// Not this reference's fault: its try is not counted
const next = $('worker: Next reference').first().json;
const manifest = $('worker: Start attempt').first().json.manifest;
const entry = manifest && Array.isArray(manifest.files) ? manifest.files.find((e) => e.queueName === next.queueName) : null;
if (!entry || entry.status !== "queued") return [{ json: { hasManifest: false } }];
entry.tries = Math.max(0, (Number(entry.tries) || 1) - 1);
return [{ json: { hasManifest: true }, binary: { manifest: { data: Buffer.from(JSON.stringify(manifest, null, 2)).toString("base64"), mimeType: "application/json", fileName: next.batchId + "_batch.json" } } }];

parameters.text:
Check the attached image.
clean = false if it contains ANY of these:
- a color palette, color swatches, color chips or a legend: flat squares or a strip of sample colors laid out along an edge, not part of the scene;
- readable text: words you can actually read on a sign, a poster, a label or an inscription, or a signature or watermark;
- a plain white or grey margin, a mat, a picture frame, a mockup, a canvas edge or paper around the whole painting;
- a pixelated look: visible square pixels or a grid of equal square blocks, like a low-resolution image or pixel art.
Part of the design is NOT a problem: a decorative patterned border that belongs to the artwork (a zellij, rug or ornamental band), geometric tile patterns, mosaics and star patterns (zellij), a window, doorway, arch or picture frame painted inside the scene, sun rays, stripes, rainbows or colorful patterns, blank signs, license plates (even with letters or numbers), vehicle emblems, badges and brand logos on objects, and small shapes or marks that cannot be read as words.
Otherwise clean = true. "problems" lists what you found, or is empty.

parameters.jsCode:
// A problem was found in the artwork: paint again, at most MAX_ATTEMPTS images in all
const MAX_ATTEMPTS = 3;
const attempt = $runIndex + 2; // this node runs after attempt 1, 2...
return [{
    json: { retry: attempt <= MAX_ATTEMPTS, attempt, problems: $json.output ? $json.output.problems : "" },
    binary: $('worker: Prepare').first().binary,
}];

// 3 paintings, none clean: the reference is set aside in Artwork Ref/Failed
const last = $('worker: Count attempts').last().json;
return [{ json: { status: "failed", reason: "not painted cleanly in 3 tries" + (last.problems ? " (" + last.problems + ")" : "") } }];

// The new folder is the next free number: 1001, 1002, ... (folders with other names are ignored)
const first = Number($('worker: Settings').first().json.firstFolderNumber) || 1001;
const numbers = (($input.first().json.files) || []).map((f) => String(f.name).trim()).filter((n) => /^\d+$/.test(n)).map(Number);
const next = numbers.length ? Math.max(first - 1, ...numbers) + 1 : first;
return [{ json: { folderName: String(next) } }];

// Artwork Ref + the palette JSON + Artwork Gen, one item per file, named after the folder: 1095_ref.jpg,
// 1095_palette.json, 1095_art.png. The artwork goes last: a folder only counts for Titling, Print and the Watchdog
// once it has its artwork, so a run that stops midway leaves no half folder behind.
const folderId = $input.first().json.id;
const base = $('worker: Next folder number').first().json.folderName;
const prepared = $('worker: Prepare').first();
const names = folderFileNames(base, $('worker: Next reference').first().json.extension);
const paletteJson = { ...$('worker: Check palette').first().json.paletteJson, artwork: names.artwork, reference: names.reference };
return [
    { json: { folderId, name: names.reference }, binary: { data: { ...prepared.binary.reference, fileName: names.reference } } },
    {
        json: { folderId, name: names.palette },
        binary: { data: { data: Buffer.from(JSON.stringify(paletteJson, null, 2)).toString("base64"), mimeType: "application/json", fileName: names.palette } },
    },
    { json: { folderId, name: names.artwork }, binary: { data: { ...$('worker: Artwork file').first().binary.artwork, fileName: names.artwork } } },
];
function folderFileNames(base, extension) {
    return { reference: base + "_ref." + extension, palette: base + "_palette.json", artwork: base + "_art.png" };
}

const folder = $('worker: Create folder (Artwork Agent/1xxx)').first().json;
// the reference keeps its folder name in Artwork Ref too: 1095_ref.jpg
return [{ json: { status: "done", folder: folder.name, folderId: folder.id, referenceName: folder.name + "_ref." + $('worker: Next reference').first().json.extension } }];

// The manifest records what became of the reference; the batch is painted once nothing of it is queued
const settings = $('worker: Settings').first().json;
const next = $('worker: Next reference').first().json;
const result = $input.first().json;
const manifest = $('worker: Start attempt').first().json.manifest;
const now = $now.setZone(settings.timezone).toISO();
let painted = false;
if (manifest && Array.isArray(manifest.files)) {
    const entry = manifest.files.find((e) => e.queueName === next.queueName);
    if (entry) Object.assign(entry, { status: result.status, reason: result.reason || "", folder: result.folder || "", folderId: result.folderId || "", referenceName: result.referenceName || "", finishedAt: result.recovered && entry.finishedAt ? entry.finishedAt : now });
    painted = manifest.files.every((e) => e.status !== "queued");
    if (painted) Object.assign(manifest, { paintedAt: now, notified: false });
}
// a painted reference goes to Artwork Ref under its new name, a failed one to Artwork Ref/Failed as it is
const move = result.status === "done"
    ? { to: settings.refFolderId, name: result.referenceName || next.queueName }
    : { to: settings.failedFolderId, name: next.queueName };
const out = { json: { status: result.status, folder: result.folder || "", folderId: result.folderId || "", reason: result.reason || "", recovered: !!result.recovered, painted, hasManifest: !!manifest, move, manifest } };
if (manifest) out.binary = { manifest: { data: Buffer.from(JSON.stringify(manifest, null, 2)).toString("base64"), mimeType: "application/json", fileName: next.batchId + "_batch.json" } };
return [out];

// The artwork (a photo with its product number) or, when it could not be painted, the reason
const next = $('worker: Next reference').first().json;
const entryResult = $('worker: Update entry').first().json;
const manifest = $('worker: Start attempt').first().json.manifest;
const originalName = $('worker: Start attempt').first().json.originalName;
let position = "";
if (manifest && Array.isArray(manifest.files)) {
    const i = manifest.files.findIndex((e) => e.queueName === next.queueName);
    if (i >= 0) position = ", " + (i + 1) + " of " + manifest.files.length;
}
const from = "From: " + originalName + " (batch " + next.batchId + position + ")";
// finished by a later run (the first one stopped before this message): a text, the artwork image is not at hand
if (entryResult.recovered) {
    const lines = entryResult.status === "done"
        ? ["Artwork " + entryResult.folder + " painted", from, "https://drive.google.com/drive/folders/" + entryResult.folderId]
        : ["Not painted: " + originalName, from, "Reason: " + entryResult.reason, "The reference is in Artwork Ref/Failed."];
    return [{ json: { painted: false, text: lines.join("\n") } }];
}
if (entryResult.status === "done") {
    const folder = $('worker: Create folder (Artwork Agent/1xxx)').first().json;
    const colors = $('worker: Check palette').first().json.paletteJson.colorCount;
    const caption = [
        "Artwork " + folder.name + " painted, " + colors + " Darl'Art colors",
        from,
        "Next: product texts, print files and mockup, then the Shopify draft.",
        "https://drive.google.com/drive/folders/" + folder.id,
    ].join("\n");
    return [{ json: { painted: true, caption }, binary: { data: $('worker: Artwork file').first().binary.artwork } }];
}
const reason = $('worker: Result: not painted').isExecuted ? $('worker: Result: not painted').first().json.reason : $('worker: Result: stopped too often').isExecuted ? $('worker: Result: stopped too often').first().json.reason : $('worker: Result: refused').isExecuted ? $('worker: Result: refused').first().json.reason : "";
return [{ json: { painted: false, text: ["Not painted: " + originalName, from, "Reason: " + reason, "The reference is in Artwork Ref/Failed."].join("\n") } }];

const next = $('worker: Next reference').first().json;
const manifest = $('worker: Update entry').first().json.manifest;
const done = manifest.files.filter((e) => e.status === "done");
const failed = manifest.files.filter((e) => e.status === "failed");
const lines = ["Batch " + next.batchId + " painted: " + done.length + " artwork" + (done.length === 1 ? "" : "s") + (done.length ? " (" + done.map((e) => e.folder).join(", ") + ")" : "")];
if (failed.length) {
    lines.push("", failed.length + " not painted:");
    for (const e of failed) lines.push("- " + e.originalName + ": " + (e.reason || "failed"));
}
if (done.length) lines.push("", "You get one more message when all their drafts are in Shopify.");
return [{ json: { text: lines.join("\n") } }];

// Batch manifests in the queue, now that no reference is left in it
const files = $('worker: List queue').first().json.files || [];
const manifests = files.filter((f) => /^.+_batch[.]json$/.test(f.name));
return manifests.length ? manifests.map((f) => ({ json: { manifestId: f.id, name: f.name } })) : [{ json: { none: true } }];

// A batch is finished when none of its references is still queued; after an hour, a queued reference that is not in
// the queue never got there (the upload stopped): it is marked failed
const settings = $('worker: Settings').first().json;
const leftovers = $('worker: Leftover manifests').all().map((item) => item.json);
const now = $now.setZone(settings.timezone).toISO();
const out = [];
$input.all().forEach((item, i) => {
    const manifest = item.json;
    if (!manifest || !Array.isArray(manifest.files) || !leftovers[i]) return;
    const old = !manifest.submittedAt || Date.now() - new Date(manifest.submittedAt).getTime() > 3600000;
    const queued = manifest.files.filter((e) => e.status === "queued");
    if (queued.length && !old) return;
    for (const e of queued) Object.assign(e, { status: "failed", reason: "the upload did not reach the queue", finishedAt: now });
    if (!manifest.paintedAt) Object.assign(manifest, { paintedAt: now, notified: false });
    out.push({
        json: { manifestId: leftovers[i].manifestId },
        binary: { manifest: { data: Buffer.from(JSON.stringify(manifest, null, 2)).toString("base64"), mimeType: "application/json", fileName: leftovers[i].name } },
    });
});
return out.length ? out : [{ json: { none: true } }];

// My lock, plus locks left behind by crashed runs
const processed = $('worker: Next reference').isExecuted && !$('worker: Next reference').first().json.none;
const ids = [$('worker: Won the lock?').first().json.lockId, ...$('worker: Lock state').first().json.stale];
return ids.map((id) => ({ json: { id, processed: !!processed } }));

// Another run holds a fresh lock (refreshed within its stale time, kept in its description)
const OWN = 15;
const staleMs = (l) => { const m = /staleMinutes=(\d+)/.exec(l.description || ""); return (m ? Number(m[1]) : OWN) * 60000; };
const isFresh = (l) => Date.now() - new Date(l.modifiedTime || l.createdTime).getTime() < staleMs(l);
const locks = $input.first().json.files || [];
const fresh = locks.filter(isFresh);
const stale = locks.filter((l) => !fresh.includes(l)).map((l) => l.id);
return [{ json: { free: fresh.length === 0, fresh: fresh.length, stale } }];

// Two runs can create a lock at the same moment: the oldest fresh lock wins, the other run steps back
const mine = $('titling: Create lock').last().json;
const OWN = 15;
const staleMs = (l) => { const m = /staleMinutes=(\d+)/.exec(l.description || ""); return (m ? Number(m[1]) : OWN) * 60000; };
const isFresh = (l) => Date.now() - new Date(l.modifiedTime || l.createdTime).getTime() < staleMs(l);
const fresh = ($input.first().json.files || [])
    .filter((l) => l.id === mine.id || isFresh(l))
    .sort((a, b) => (a.createdTime < b.createdTime ? -1 : a.createdTime > b.createdTime ? 1 : a.id < b.id ? -1 : 1));
return [{ json: { won: fresh.length > 0 && fresh[0].id === mine.id, lockId: mine.id } }];

// One theme per collection family: "Animals", "Animals - Mini Kits" and "Kids - Animals" (or "Animals - Kids Kits")
// are the theme "Animals".
// Its tag is the main collection's handle (the Kids Kits smart collections match on it, e.g. "animals").
const settings = $('titling: Settings').first().json;
const response = $input.first().json;
const errors = (response.errors || []).map((e) => e.message);
if (errors.length) throw new Error("Shopify: " + errors.join("; "));
const collections = ((response.data || {}).collections || {}).nodes || [];
const skip = new Set(String(settings.skipCollections).split(",").map((s) => s.trim().toLowerCase()).filter(Boolean));
const slug = (s) => String(s).toLowerCase().replace(/&/g, " ").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
const themes = {};
for (const c of collections) {
    if (skip.has(c.title.trim().toLowerCase())) continue;
    // "Kids - Animals": the Kids Kits collection of the theme after "Kids - "
    const kidsPrefix = /^kids\s*-\s*(.+)$/i.exec(c.title.trim());
    const name = kidsPrefix ? kidsPrefix[1].trim() : c.title.split(" - ")[0].trim();
    const theme = (themes[name] = themes[name] || { name, tag: slug(name), collections: [] });
    // smart: an automated collection (its rules pick the products, e.g. by tag); a product can't be put in it by hand
    const kids = !!kidsPrefix || /-\s*kids kits$/i.test(c.title);
    theme.collections.push({ id: c.id, title: c.title, handle: c.handle, smart: !!c.ruleSet, kids });
    if (c.title.trim() === name) theme.tag = c.handle; // the main collection's handle
}
// themes with a main collection (e.g. "Animals"), for every painting; themes with only a Kids Kits collection
// (e.g. "Kids - Space"), for kids paintings only. A Mini Kits collection alone never makes a theme.
for (const t of Object.values(themes)) t.kidsOnly = !t.collections.some((c) => c.title.trim() === t.name) && t.collections.some((c) => c.kids);
const list = Object.values(themes).filter((t) => !t.kidsOnly && t.collections.some((c) => c.title.trim() === t.name) || t.kidsOnly).sort((a, b) => a.name.localeCompare(b.name));
if (!list.length) throw new Error("No theme collections found in Shopify");
// the allowed values of the collection-page filters (Settings > Custom data > Products): Category, Difficulty level
const choicesOf = (key) => {
    const d = (((response.data || {}).metafieldDefinitions || {}).nodes || []).find((n) => n.key === key);
    const v = d && (d.validations || []).find((x) => x.name === "choices");
    try { return v ? JSON.parse(v.value) : []; } catch (e) { return []; }
};
return [{ json: { themes: list, names: list.filter((t) => !t.kidsOnly).map((t) => t.name), kidsNames: list.filter((t) => t.kidsOnly).map((t) => t.name), categoryChoices: choicesOf("category"), difficultyChoices: choicesOf("difficulty_level") } }];

// One item per numbered folder (1001, 1002...), oldest first
const folders = ($input.first().json.files || []).filter((f) => /^\d+$/.test(String(f.name).trim()) && (f.appProperties || {}).darlart_family === "kids" && !["migrating", "review", "validation"].includes((f.appProperties || {}).darlart_state));
folders.sort((a, b) => Number(a.name) - Number(b.name));
if (!folders.length) return [{ json: { none: true } }];
return folders.map((f) => ({ json: { id: f.id, name: String(f.name).trim() } }));

// Keeps the folders that have an artwork (1095_art.png) and no 1095_product.json yet, and were not
// given up (maxTries tries); folders never tried first, then the oldest
const settings = $('titling: Settings').first().json;
const maxTries = Number(settings.maxTries) || 3;
const folders = $('titling: Folders').all();
const pending = [];
$input.all().forEach((item, i) => {
    const folder = folders[i].json;
    if (folder.none) return;
    const files = item.json.files || [];
    const art = files.find((f) => /^.+_art\.png$/.test(f.name));
    if (!art) return;
    // the files' prefix: the folder number (a date+time in folders made before 2026-10-05)
    const stamp = art.name.slice(0, -"_art.png".length);
    const productName = stamp + "_product.json";
    if (files.some((f) => f.name === productName)) return;
    const tries = files.filter((f) => f.name.startsWith("_titling-try-")).length;
    if (tries >= maxTries || files.some((f) => f.name === "_titling-gave-up")) return;
    const ref = files.find((f) => f.name.startsWith(stamp + "_ref."));
    pending.push({ json: { folderId: folder.id, folder: folder.name, stamp, artworkId: art.id, artworkName: art.name, referenceName: ref ? ref.name : "", productName, tries } });
});
pending.sort((a, b) => a.json.tries - b.json.tries || Number(a.json.folder) - Number(b.json.folder));
const todo = pending.slice(0, Number(settings.maxPerRun) || 20);
return todo.length ? todo : [{ json: { none: true } }];

// Folders tried maxTries times that still have no product JSON and no "_titling-gave-up" marker yet
const settings = $('titling: Settings').first().json;
const maxTries = Number(settings.maxTries) || 3;
const folders = $('titling: Folders').all();
const out = [];
$input.all().forEach((item, i) => {
    const folder = folders[i].json;
    if (folder.none) return;
    const files = item.json.files || [];
    const art = files.find((f) => /^.+_art\.png$/.test(f.name));
    if (!art || files.some((f) => f.name === art.name.slice(0, -"_art.png".length) + "_product.json")) return;
    const tries = files.filter((f) => f.name.startsWith("_titling-try-")).length;
    if (tries >= maxTries && !files.some((f) => f.name === "_titling-gave-up")) out.push({ json: { folderId: folder.id, folder: folder.name, tries } });
});
return out.length ? out : [{ json: { none: true } }];

const settings = $('titling: Settings').first().json;
const up = $('titling: Given up folders').all().map((item) => item.json).filter((f) => !f.none);
if (!up.length || !String(settings.telegramChatId || "").trim()) return [{ json: { none: true } }];
return [{ json: { text: ["Titling Agent: gave up on folder" + (up.length === 1 ? " " : "s ") + up.map((f) => f.folder).join(", ") + " after " + settings.maxTries + " tries (no product texts).", "", "Its print files are still made, but it gets no Shopify draft until it has its product JSON. To try again, delete the files named _titling-... in the folder. The last error is in the Error Handler's alerts."].join("\n") } }];

