parameters.jsCode:
// The product JSON, in Shopify's field names, saved next to the artwork as <folder>_product.json
const settings = $('titling: Settings').first().json;
const folder = $('titling: Loop over folders').first().json;
const themes = $('titling: Themes').first().json.themes;
// The family is selected at upload; the Classic form cannot create Kids products.
const out = { ...($json.output || {}), kids: true };

const title = String(out.title || "").replace(/\s+/g, " ").trim().slice(0, 70);
if (!title) throw new Error("No title for folder " + folder.folder);
const handle = title.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/&/g, " ").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

// only themes that exist in the store; their tags make the smart collections (e.g. Kids Kits) pick the product up
const chosen = [];
for (const name of out.themes || []) {
    const theme = themes.find((t) => t.name.toLowerCase() === String(name).trim().toLowerCase());
    // a kids-only theme (e.g. Space: only "Kids - Space" exists) is kept for a kids painting only
    if (theme && !chosen.includes(theme) && (!theme.kidsOnly || out.kids === true)) chosen.push(theme);
}
// one collection per painting: keep the first valid theme only
chosen.splice(1);
// a kids painting goes in each theme's "<theme> - Kids Kits" collection instead of the main one (the main one when the
// theme has no Kids Kits collection); an automated Kids Kits collection picks it up by its tags (kids-kits + the theme)
const kids = out.kids === true;
const categoryChoices = $('titling: Themes').first().json.categoryChoices || [];
const difficultyChoices = $('titling: Themes').first().json.difficultyChoices || [];
// a kids painting is always "Beginner"; an answer outside the allowed values becomes "Intermediate"
const pickDifficulty = (want) => difficultyChoices.find((d) => d.toLowerCase() === String(want || "").trim().toLowerCase()) || "";
const difficulty = false ? (pickDifficulty("Beginner") || "Beginner") : (pickDifficulty(out.difficulty) || pickDifficulty("Intermediate") || "");
const collections = chosen.map((t) => {
    const main = t.collections.find((c) => c.title === t.name);
    const kidsKits = kids ? t.collections.find((c) => c.kids) : null;
    return kidsKits || main;
}).filter((c) => c && !c.smart);

// plain text: any HTML the model adds anyway becomes paragraph breaks
const description = String(out.description || "")
    .replace(/<\/p>\s*<p[^>]*>/gi, "\n\n").replace(/<br\s*\/?>/gi, "\n").replace(/<[^>]+>/g, "")
    .replace(/[ \t]+/g, " ").replace(/\s*\n\s*\n\s*/g, "\n\n").trim();

const tags = [];
for (const tag of [...String(settings.baseTags).split(","), ...(kids ? ["kids-kits"] : []), ...chosen.map((t) => t.tag), ...(out.tags || [])]) {
    const clean = String(tag).toLowerCase().replace(/\s+/g, " ").trim();
    if (clean && !tags.includes(clean)) tags.push(clean);
}

const product = {
    title,
    handle,
    description,
    productType: settings.productType,
    vendor: settings.vendor,
    themes: chosen.map((t) => t.name),
    kids,
    // the collection-page filters: Category = the product's themes (allowed values only), Difficulty level
    category: chosen.map((t) => t.name).filter((n) => !categoryChoices.length || categoryChoices.includes(n)).slice(0, 5),
    difficulty,
    collections: collections.map((c) => ({ id: c.id, title: c.title, handle: c.handle })),
    tags,
    needsReview: chosen.length === 0 ? "no theme from the store matched: choose the collection by hand" : "",
    source: { folder: folder.folder, artwork: folder.artworkName, reference: folder.referenceName, palette: folder.stamp + "_palette.json" },
    generatedAt: $now.setZone("Africa/Casablanca").toISO(),
};
return [{
    json: { folder: folder.folder, title, file: folder.productName },
    binary: { data: { data: Buffer.from(JSON.stringify(product, null, 2)).toString("base64"), mimeType: "application/json", fileName: folder.productName } },
}];

// What this run produced (visible in the execution log)
const saved = $input.all().map((item) => item.json.name).filter(Boolean);
return [{ json: { saved: saved.length, files: saved } }];

// My lock, plus locks left behind by crashed runs
const processed = $('titling: Summary').isExecuted && $('titling: Summary').first().json.saved > 0;
const ids = [$('titling: Won the lock?').first().json.lockId, ...$('titling: Lock state').first().json.stale];
return ids.map((id) => ({ json: { id, processed: !!processed } }));

// Another run holds a fresh lock (refreshed within its stale time, kept in its description)
const OWN = Number($('print: Settings').first().json.lockStaleMinutes);
const staleMs = (l) => { const m = /staleMinutes=(\d+)/.exec(l.description || ""); return (m ? Number(m[1]) : OWN) * 60000; };
const isFresh = (l) => Date.now() - new Date(l.modifiedTime || l.createdTime).getTime() < staleMs(l);
const locks = $input.first().json.files || [];
const fresh = locks.filter(isFresh);
const stale = locks.filter((l) => !fresh.includes(l)).map((l) => l.id);
return [{ json: { free: fresh.length === 0, fresh: fresh.length, stale } }];

// Two runs can create a lock at the same moment: the oldest fresh lock wins, the other run steps back
const mine = $('print: Create lock').last().json;
const OWN = Number($('print: Settings').first().json.lockStaleMinutes);
const staleMs = (l) => { const m = /staleMinutes=(\d+)/.exec(l.description || ""); return (m ? Number(m[1]) : OWN) * 60000; };
const isFresh = (l) => Date.now() - new Date(l.modifiedTime || l.createdTime).getTime() < staleMs(l);
const fresh = ($input.first().json.files || [])
    .filter((l) => l.id === mine.id || isFresh(l))
    .sort((a, b) => (a.createdTime < b.createdTime ? -1 : a.createdTime > b.createdTime ? 1 : a.id < b.id ? -1 : 1));
return [{ json: { won: fresh.length > 0 && fresh[0].id === mine.id, lockId: mine.id } }];

// One item per numbered folder (1001, 1002...), oldest first
const folders = ($input.first().json.files || []).filter((f) => /^\d+$/.test(String(f.name).trim()) && (f.appProperties || {}).darlart_family === "kids" && !["migrating", "review", "validation"].includes((f.appProperties || {}).darlart_state));
folders.sort((a, b) => Number(a.name) - Number(b.name));
if (!folders.length) return [{ json: { none: true } }];
return folders.map((f) => ({ json: { id: f.id, name: String(f.name).trim() } }));

// Folders with an artwork: its files' prefix (the folder number, a date+time in older folders), the Print subfolder (if any) and the files already there
const folders = $('print: Folders').all();
const states = [];
$input.all().forEach((item, i) => {
    const folder = folders[i].json;
    if (folder.none) return;
    const files = item.json.files || [];
    const art = files.find((f) => /^.+_art\.png$/.test(f.name));
    if (!art) return;
    const print = files.find((f) => f.name === "Print" && f.mimeType === "application/vnd.google-apps.folder");
    states.push({ json: { folderId: folder.id, folder: folder.name, stamp: art.name.slice(0, -"_art.png".length), artworkId: art.id, printFolderId: print ? print.id : "", rootFiles: files.map((f) => f.name) } });
});
return states.length ? states : [{ json: { none: true } }];

// Folders with an artwork and no <folder>_featured.png yet (at most maxPerRun per run)
const settings = $('print: Settings').first().json;
const todo = $('print: Folder states').all().map((item) => item.json)
    .filter((state) => !state.none && !state.rootFiles.includes(state.stamp + "_featured.png"))
    .slice(0, Number(settings.maxPerRun) || 5)
    .map((state) => ({ json: { folderId: state.folderId, folder: state.folder, artworkId: state.artworkId, name: state.stamp + "_featured.png" } }));
return todo.length ? todo : [{ json: { none: true } }];

// The API's PNGs (base64) as files; a folder whose image failed is retried by the next run
const todo = $('print: Featured to make').all();
const out = [];
$input.all().forEach((item, i) => {
    const folder = todo[i].json;
    if (!item.json.image) return;
    out.push({ json: folder, binary: { data: { data: item.json.image, mimeType: "image/png", fileName: folder.name, fileExtension: "png" } } });
});
return out.length ? out : [{ json: { none: true } }];

// One job per canvas size x color count still missing; the mockup job goes last in its folder (it marks the folder done)
const settings = $('print: Settings').first().json;
const states = $('print: Folder states').all();
const colors = String(settings.colorsList).split(",").map((c) => Number(c.trim())).filter((c) => c > 1);
const sizes = String(settings.canvasSizes).split(",").map((s) => s.trim().toLowerCase().replace(/\s+/g, "")).filter(Boolean);
const mockupColors = Number(settings.mockupColors);
const flip = (size) => size.split("x").reverse().join("x");
const jobs = [];
let folderCount = 0;
$('print: List Print files').all().forEach((item, i) => {
    const state = states[i].json;
    if (state.none || folderCount >= Number(settings.maxPerRun)) return;
    // given up after maxFailedRuns runs with failed jobs (delete its "_print-failed-" markers to try again)
    if (state.rootFiles.filter((n) => n.startsWith(state.stamp + "_print-failed-")).length >= Number(settings.maxFailedRuns || 3)) return;
    const printFiles = new Set((item.json.files || []).map((f) => f.name));
    // 1095_12_blank.svg, or with the size (several sizes made, or a folder from before 2026-10-05): ..._60x75_12_blank.svg
    const has = (size, n, suffix) => (sizes.length === 1 && printFiles.has(state.stamp + "_" + n + suffix))
        || printFiles.has(state.stamp + "_" + size + "_" + n + suffix) || printFiles.has(state.stamp + "_" + flip(size) + "_" + n + suffix);
    const needMockupFile = !state.rootFiles.includes(state.stamp + "_mockup.png");
    const folderJobs = [];
    sizes.forEach((size, s) => {
        for (const n of colors) {
            const needSvg = !has(size, n, "_blank.svg");
            const needPdf = !has(size, n, "_catalog.pdf");
            const needUser = !has(size, n, "_user.pdf");
            const needMockup = needMockupFile && s === 0 && n === mockupColors;
            if (needSvg || needPdf || needUser || needMockup) folderJobs.push({ size, colors: n, needSvg, needPdf, needUser, needMockup });
        }
    });
    if (needMockupFile && !folderJobs.some((j) => j.needMockup)) {
        folderJobs.push({ size: sizes[0], colors: mockupColors, needSvg: false, needPdf: false, needUser: false, needMockup: true });
    }
    if (!folderJobs.length) return;
    folderCount++;
    folderJobs.sort((a, b) => Number(a.needMockup) - Number(b.needMockup));
    for (const job of folderJobs) {
        jobs.push({ json: { folderId: state.folderId, folder: state.folder, stamp: state.stamp, withSize: sizes.length > 1, artworkId: state.artworkId, printFolderId: state.printFolderId, ...job } });
    }
});
return jobs.length ? jobs : [{ json: { none: true } }];

// One item per folder with jobs, to make sure its Print subfolder exists
const seen = new Set();
const out = [];
for (const item of $input.all()) {
    if (seen.has(item.json.folderId)) continue;
    seen.add(item.json.folderId);
    out.push({ json: { folderId: item.json.folderId, printFolderId: item.json.printFolderId } });
}
return out;

// Every job now knows its Print folder
const prepared = $('print: Folders to prepare').all();
const printIds = {};
$input.all().forEach((item, i) => {
    if (item.json.mimeType !== "application/vnd.google-apps.folder") throw new Error("Print folder for " + prepared[i].json.folderId + " is not a folder: " + JSON.stringify(item.json));
    printIds[prepared[i].json.folderId] = item.json.id;
});
return $('print: Plan jobs').all().map((item) => ({ json: { ...item.json, printFolderId: printIds[item.json.folderId] } }));

// The jobs' state (built from the planned jobs the first time), and the jobs to send now: as many as there are free
// places among parallelJobs
const settings = $('print: Settings').first().json;
const first = $input.first().json;
const state = Array.isArray(first.jobs) ? first : {
    jobs: $input.all().map((item) => ({ ...item.json, jobId: "", status: "pending", error: "", sentAt: 0, result: null, saved: false })),
    saved: [],
    errors: [],
};
const places = Math.max(1, Number(settings.parallelJobs) || 1) - state.jobs.filter((j) => j.status === "sent").length;
const send = [];
state.jobs.forEach((j, i) => { if (j.status === "pending" && send.length < places) send.push(i); });
return [{ json: { ...state, send } }];

// The sent jobs get their pbn job id; a job the API did not accept has failed (the next run tries it again)
const state = JSON.parse(JSON.stringify($('print: Job round').first().json));
const answers = $input.first().json.none ? [] : $input.all().map((item) => item.json);
state.send.forEach((index, k) => {
    const job = state.jobs[index];
    const a = answers[k] || {};
    if (a.jobId) Object.assign(job, { jobId: a.jobId, status: "sent", sentAt: Date.now() });
    else Object.assign(job, { status: "failed", error: String((a.error && (a.error.message || a.error)) || a.message || "pbn job not accepted").slice(0, 300) });
});
state.send = [];
return [{ json: state }];

// Each sent job's state. A job the API no longer knows (restarted) has failed; so has one with no result
// 2 x jobTimeoutMinutes + 5 after it was sent (the API gives up on a job after jobTimeoutMinutes itself).
// The files of the jobs finished now are saved this round; a folder's mockup (it marks the folder done for the
// Watchdog) once all the folder's jobs are finished, and only if none failed.
const settings = $('print: Settings').first().json;
const checked = !Array.isArray($input.first().json.jobs);
const state = JSON.parse(JSON.stringify($('print: Jobs sent').first().json));
if (checked) {
    const asked = $('print: Jobs to check').all().map((item) => item.json.jobId);
    const answers = $input.all().map((item) => item.json);
    const limit = (2 * Number(settings.jobTimeoutMinutes || 10) + 5) * 60000;
    asked.forEach((jobId, k) => {
        const job = state.jobs.find((j) => j.jobId === jobId);
        const a = answers[k] || {};
        if (!job) return;
        if (a.jobId === jobId && a.status === "completed" && a.result) {
            if (a.result.colorsUsed !== 18 || a.result.colorsRequested !== 18) { Object.assign(job, { status: "failed", error: "Kids template must use exactly 18 paints" }); return; }
            job.status = "completed";
            job.result = { label: (a.result.canvas && a.result.canvas.label) || job.size, files: (a.result.files || []).map((x) => ({ name: x.name, url: x.url })) };
        } else if (a.jobId === jobId && a.status === "failed") Object.assign(job, { status: "failed", error: String(a.error || "failed").slice(0, 300) });
        else if (JSON.stringify(a).includes("Job not found")) Object.assign(job, { status: "failed", error: "the pbn API no longer has this job (restarted?)" });
        else if (Date.now() - job.sentAt > limit) Object.assign(job, { status: "failed", error: "no result " + Math.round(limit / 60000) + " min after it was sent" });
    });
}
const files = [];
for (const job of state.jobs) {
    if (job.status !== "completed" || job.saved) continue;
    const url = (name) => (job.result.files.find((x) => x.name === name) || {}).url;
    const want = [];
    // 1095_12_blank.svg; the canvas size is in the name only when several sizes are made
    const prefix = job.stamp + "_" + (job.withSize ? job.result.label + "_" : "") + job.colors;
    // the Blank SVG (grey outlines, black numbers, no colors): the file printed on the canvas
    if (job.needSvg) want.push({ url: url("blank.svg"), name: prefix + "_blank.svg", parent: job.printFolderId });
    if (job.needPdf) want.push({ url: url("painting.pdf"), name: prefix + "_catalog.pdf", parent: job.printFolderId });
    if (job.needUser) want.push({ url: url("template.pdf"), name: prefix + "_user.pdf", parent: job.printFolderId });
    if (job.needMockup && !url("mockup.png")) want.push({ url: "" });
    if (want.some((w) => !w.url)) {
        Object.assign(job, { status: "failed", error: "the pbn API result is missing a file" });
        continue;
    }
    files.push(...want);
    job.saved = true;
}
// mockups: a folder whose jobs are all finished, none failed
for (const job of state.jobs) {
    if (!job.needMockup || job.status !== "completed" || job.mockupSaved) continue;
    const folderJobs = state.jobs.filter((j) => j.folder === job.folder);
    if (folderJobs.some((j) => j.status === "pending" || j.status === "sent" || j.status === "failed")) continue;
    files.push({ url: job.result.files.find((x) => x.name === "mockup.png").url, name: job.stamp + "_mockup.png", parent: job.folderId });
    job.mockupSaved = true;
}
state.finished = !state.jobs.some((j) => j.status === "pending" || j.status === "sent");
state.checks = (state.checks || 0) + (checked ? 1 : 0);
return [{ json: { ...state, toSave: files } }];

// The files saved this round (a file Drive or the API refused comes back as an error item: the next run retries it)
const state = JSON.parse(JSON.stringify($('print: Jobs checked').first().json));
if (!$input.first().json.none) {
    for (const item of $input.all()) {
        const j = item.json;
        if (j.id && j.name) state.saved.push(j.name);
        else state.errors.push(String((j.error && (j.error.message || j.error)) || "file not saved").slice(0, 300));
    }
}
// the jobs' results are no longer needed once saved: the state stays small
for (const job of state.jobs) if (job.saved && (!job.needMockup || job.mockupSaved)) job.result = null;
state.toSave = [];
return [{ json: state }];

// Files saved in this run, and the jobs that failed (retried by the next run)
const state = $('print: Round saved').first().json;
const failed = state.jobs.filter((j) => j.status === "failed").map((j) => ({ folder: j.folder, job: j.size + " " + j.colors + " colors", reason: j.error }));
return [{ json: { saved: state.saved.length, files: state.saved, failed, errors: state.errors } }];

// One marker per folder with failed jobs in this run, and the folders given up now
const settings = $('print: Settings').first().json;
const summary = $('print: Run summary').first().json;
const states = $('print: Folder states').all().map((item) => item.json).filter((s) => !s.none);
const byFolder = {};
for (const f of summary.failed || []) (byFolder[f.folder] = byFolder[f.folder] || []).push(f.job + ": " + f.reason);
const out = [];
for (const [folder, reasons] of Object.entries(byFolder)) {
    const state = states.find((s) => s.folder === folder);
    if (!state) continue;
    const before = state.rootFiles.filter((n) => n.startsWith(state.stamp + "_print-failed-")).length;
    out.push({ json: {
        folder, folderId: state.folderId, name: state.stamp + "_print-failed-" + $execution.id,
        description: reasons.join("; ").slice(0, 900),
        givenUp: before + 1 >= Number(settings.maxFailedRuns || 3), runs: before + 1, reasons,
    } });
}
return out.length ? out : [{ json: { none: true } }];

// One alert per folder given up in this run
const settings = $('print: Settings').first().json;
const up = $('print: Failed folders').all().map((item) => item.json).filter((f) => f.givenUp);
if (!up.length || !String(settings.telegramChatId || "").trim()) return [{ json: { none: true } }];
const lines = ["Print Agent: gave up on " + up.length + " folder" + (up.length === 1 ? "" : "s") + " after " + settings.maxFailedRuns + " failed runs"];
for (const f of up) lines.push("", "- " + f.folder + ": " + f.reasons.slice(0, 4).join("; "));
lines.push("", "Its print files and mockup are not made, so no Shopify draft. To try again, delete the files named ..._print-failed-... in the folder.");
return [{ json: { text: lines.join("\n").slice(0, 4000) } }];

// This run's successful generations, added to the tally; sent once when a run finds nothing left to do
const settings = $('print: Settings').first().json;
const file = ($input.first().json.files || [])[0] || null;
let tally = { folders: {}, since: $now.toISO() };
try { if (file && file.description) tally = JSON.parse(file.description); } catch (e) {}
const stampToFolder = {};
if ($('print: Plan jobs').isExecuted) for (const item of $('print: Plan jobs').all()) if (!item.json.none) stampToFolder[item.json.stamp] = item.json.folder;
const add = (folder, kind) => { const f = (tally.folders[folder] = tally.folders[folder] || {}); f[kind] = (f[kind] || 0) + 1; };
let made = 0;
const files = $('print: Run summary').isExecuted ? $('print: Run summary').first().json.files || [] : [];
for (const name of files) {
    const kind = name.endsWith("_blank.svg") ? "blank SVG" : name.endsWith("_catalog.pdf") ? "catalog PDF" : name.endsWith("_user.pdf") ? "user PDF" : name.endsWith("_mockup.png") ? "mockup" : "file";
    const stamp = Object.keys(stampToFolder).find((s) => name.startsWith(s + "_"));
    add(stamp ? stampToFolder[stamp] : name.split("_")[0], kind);
    made++;
}
if ($('print: Save featured image').isExecuted) {
    const todo = $('print: Featured to make').all().map((item) => item.json);
    for (const item of $('print: Save featured image').all()) {
        if (!item.json.id) continue;
        add((todo.find((t) => t.name === item.json.name) || {}).folder || item.json.name, "featured image");
        made++;
    }
}
const telegram = String(settings.telegramChatId || "").trim() !== "";
if (made) return [{ json: { action: "save", reportId: file ? file.id : "", description: JSON.stringify(tally) } }];
const folders = Object.keys(tally.folders);
if (!file || !folders.length) return [{ json: { action: "none" } }];
if (!telegram) return [{ json: { action: "drop", reportId: file.id } }];
const lines = ["Print Agent: finished, " + folders.length + " folder" + (folders.length === 1 ? "" : "s") + " done"];
let ready = 0;
for (const folder of folders.sort()) {
    const kinds = tally.folders[folder];
    const parts = [];
    for (const kind of ["blank SVG", "catalog PDF", "user PDF", "file"]) if (kinds[kind]) parts.push(kinds[kind] + " " + kind);
    if (kinds["mockup"]) parts.push("mockup");
    if (kinds["featured image"]) parts.push("featured image");
    if (kinds["mockup"]) ready++;
    lines.push("- " + folder + ": " + parts.join(", "));
}
if (ready) lines.push("", ready + " folder" + (ready === 1 ? "" : "s") + " ready for the Shopify draft.");
return [{ json: { action: "send", reportId: file.id, text: lines.join("\n").slice(0, 4000) } }];

// My lock, plus locks left behind by crashed runs
const processed = (($('print: Run summary').isExecuted ? $('print: Run summary').first().json.saved : 0) + ($('print: Save featured image').isExecuted ? $('print: Save featured image').all().filter((item) => item.json.id).length : 0)) > 0;
const ids = [$('print: Won the lock?').first().json.lockId, ...$('print: Lock state').first().json.stale];
return ids.map((id) => ({ json: { id, processed: !!processed } }));

const holds = $('print: Jobs checked').first().json.jobs.filter((j) => j.status === "failed" && /Exact color validation failed|must use exactly 18 paints/.test(j.error || ""));
const seen = new Set();
const unique = holds.filter((j) => !seen.has(j.folderId) && seen.add(j.folderId));
return unique.length ? unique.map((j) => ({ json: { folderId: j.folderId } })) : [{ json: { none: true } }];

// Another run holds a fresh lock (refreshed within its stale time, kept in its description)
const OWN = 20;
const staleMs = (l) => { const m = /staleMinutes=(\d+)/.exec(l.description || ""); return (m ? Number(m[1]) : OWN) * 60000; };
const isFresh = (l) => Date.now() - new Date(l.modifiedTime || l.createdTime).getTime() < staleMs(l);
const locks = $input.first().json.files || [];
const fresh = locks.filter(isFresh);
const stale = locks.filter((l) => !fresh.includes(l)).map((l) => l.id);
return [{ json: { free: fresh.length === 0, fresh: fresh.length, stale } }];

// Two runs can create a lock at the same moment: the oldest fresh lock wins, the other run steps back
const mine = $('upload: Create lock').last().json;
const OWN = 20;
const staleMs = (l) => { const m = /staleMinutes=(\d+)/.exec(l.description || ""); return (m ? Number(m[1]) : OWN) * 60000; };
const isFresh = (l) => Date.now() - new Date(l.modifiedTime || l.createdTime).getTime() < staleMs(l);
const fresh = ($input.first().json.files || [])
    .filter((l) => l.id === mine.id || isFresh(l))
    .sort((a, b) => (a.createdTime < b.createdTime ? -1 : a.createdTime > b.createdTime ? 1 : a.id < b.id ? -1 : 1));
return [{ json: { won: fresh.length > 0 && fresh[0].id === mine.id, lockId: mine.id } }];

const file = $input.first().json;
if (!file.id || file.trashed) throw new Error("The prices sheet (pricesSheetId in Settings) is missing or in the trash");
if (file.mimeType !== "application/vnd.google-apps.spreadsheet") throw new Error(file.name + " is not a Google Sheet: pricesSheetId must point to the prices spreadsheet");
return [{ json: { id: file.id, name: file.name, modifiedTime: file.modifiedTime } }];

// The CSV becomes the product's options and variants: Size / Canvas Type / Colors, like the store's other kits.
// A price of 0 means "not sold": no variant for that combination (the product page shows it greyed out).
const settings = $('upload: Settings').first().json;
const file = $('upload: Prices file').first().json;
const text = String($input.first().json.data || "").replace(/^\uFEFF/, "");
// empty rows of the sheet export as ",,," lines
const lines = text.split(/\r?\n/).map((l) => l.trim()).filter((l) => l.replace(/[,;"\s]/g, ""));
// one CSV line into cells; a quoted cell may hold a comma (e.g. "179,00" in a French-format sheet)
const split = (line) => {
    const cells = [];
    let cell = "";
    let quoted = false;
    for (let i = 0; i < line.length; i++) {
        const ch = line[i];
        if (quoted) {
            if (ch === '"' && line[i + 1] === '"') { cell += '"'; i++; }
            else if (ch === '"') quoted = false;
            else cell += ch;
        } else if (ch === '"') quoted = true;
        else if (ch === "," || ch === ";") { cells.push(cell.trim()); cell = ""; }
        else cell += ch;
    }
    cells.push(cell.trim());
    return cells;
};
const header = split(lines.shift() || "").map((h) => h.toLowerCase().replace(/\s+/g, "_"));
const col = (name) => header.indexOf(name);
for (const name of ["canvas_type", "size", "colors", "price"]) {
    if (col(name) < 0) throw new Error(file.name + ": missing column " + name + " (columns: canvas_type,size,colors,price)");
}
// "179", "179.00", "179,00" or "179,00 MAD"; an empty price cell counts as 0 (not sold)
const money = (value) => Number(String(value).replace(/[^\d,.-]/g, "").replace(",", ".") || "0");
const normSize = (value) => String(value || "").toLowerCase().trim().replace(/\s*cm$/, "").replace(/\s*[x×]\s*/, "x");
const soldSizes = String(settings.sizes || "").split(",").map(normSize).filter(Boolean);
const rows = [];
const seen = new Set();
lines.forEach((line, i) => {
    const cells = split(line);
    const size = normSize(cells[col("size")]);
    if (soldSizes.length && !soldSizes.includes(size)) return; // not a size the store sells
    let canvasType = cells[col("canvas_type")];
    if (!/canvas$/i.test(canvasType)) canvasType += " Canvas"; // "Rolled" -> "Rolled Canvas", the store's wording
    const colors = String(parseInt(cells[col("colors")], 10));
    const price = money(cells[col("price")]);
    const compareCell = col("compare_at_price") >= 0 ? cells[col("compare_at_price")] : "";
    const compareAt = compareCell ? money(compareCell) : price * Number(settings.compareAtMultiplier || 0);
    const where = file.name + " line " + (i + 2);
    if (!/^\d+(?:[.]\d+)?x\d+(?:[.]\d+)?$/.test(size)) throw new Error(where + ": size must look like 30x40");
    if (colors !== "18") throw new Error(where + ": Kids prices must use 18 colors");
    if (colors === "NaN") throw new Error(where + ": colors must be a number");
    if (!(price >= 0)) throw new Error(where + ": price must be a number (0 = not sold)");
    const key = size + "|" + canvasType + "|" + colors;
    if (seen.has(key)) throw new Error(where + ": " + key.replace(/\|/g, " / ") + " is listed twice");
    seen.add(key);
    const sold = price > 0;
    rows.push({ key, size, canvasType, colors, sold, price: price.toFixed(2), compareAtPrice: sold && compareAt > price ? compareAt.toFixed(2) : null });
});
if (!rows.length) throw new Error(file.name + " has no prices" + (soldSizes.length ? " for the sizes in Settings (" + soldSizes.join(", ") + ")" : ""));
const missing = soldSizes.filter((s) => !rows.some((r) => r.size === s));
if (missing.length) throw new Error(file.name + " has no prices for " + missing.join(", ") + " (sizes in Settings; a price of 0 marks a combination not sold)");
const soldRows = rows.filter((r) => r.sold);
if (!soldRows.length) throw new Error(file.name + ": every price is 0, a product needs at least one combination for sale");
if (soldRows.length > 100) throw new Error(file.name + ": Shopify allows 100 variants per product, the sheet has " + soldRows.length + " prices above 0");

const area = (s) => s.split("x").reduce((a, b) => a * Number(b), 1);
const unique = (values) => [...new Set(values)];
const order = (list) => {
    const sizes = unique(list.map((r) => r.size)).sort((a, b) => area(a) - area(b));
    const canvasTypes = unique(list.map((r) => r.canvasType)).sort();
    const colors = unique(list.map((r) => r.colors)).sort((a, b) => a - b);
    list.sort((a, b) => sizes.indexOf(a.size) - sizes.indexOf(b.size) || canvasTypes.indexOf(a.canvasType) - canvasTypes.indexOf(b.canvasType) || a.colors - b.colors);
    return { sizes, canvasTypes, colors };
};
order(rows);
// the options list only the values that have a combination for sale (Shopify has no option value without a variant)
const values = order(soldRows);
const productOptions = [
    { name: "Size", position: 1, values: values.sizes.map((name) => ({ name })) },
    { name: "Canvas Type", position: 2, values: values.canvasTypes.map((name) => ({ name })) },
    { name: "Colors", position: 3, values: values.colors.map((name) => ({ name })) },
];
const variants = soldRows.map((r, i) => ({
    optionValues: [
        { optionName: "Size", name: r.size },
        { optionName: "Canvas Type", name: r.canvasType },
        { optionName: "Colors", name: r.colors },
    ],
    price: r.price,
    compareAtPrice: r.compareAtPrice,
    position: i + 1,
    inventoryPolicy: "DENY",
    inventoryItem: { tracked: false, requiresShipping: true },
}));
return [{ json: { pricesVersion: file.modifiedTime, variantCount: variants.length, notSold: rows.length - soldRows.length, productOptions, variants, rows } }];

// One item per numbered folder (1001, 1002...), oldest first
const folders = ($input.first().json.files || []).filter((f) => /^\d+$/.test(String(f.name).trim()) && (f.appProperties || {}).darlart_family === "kids" && !["migrating", "review", "validation"].includes((f.appProperties || {}).darlart_state));
folders.sort((a, b) => Number(a.name) - Number(b.name));
if (!folders.length) return [{ json: { none: true } }];
return folders.map((f) => ({ json: { id: f.id, name: String(f.name).trim() } }));

// Keeps the folders that have their product JSON, artwork, featured image and mockup, and no <folder>_shopify.json yet,
// and were not given up (maxTries tries); folders never tried first, then the oldest
const settings = $('upload: Settings').first().json;
const maxTries = Number(settings.maxTries) || 3;
const folders = $('upload: Folders').all();
const pending = [];
$input.all().forEach((item, i) => {
    const folder = folders[i].json;
    if (folder.none) return;
    const files = item.json.files || [];
    const art = files.find((f) => /^.+_art\.png$/.test(f.name));
    if (!art) return;
    // the files' prefix: the folder number (a date+time in folders made before 2026-10-05)
    const stamp = art.name.slice(0, -"_art.png".length);
    const find = (suffix) => files.find((f) => f.name === stamp + suffix);
    const product = find("_product.json");
    const mockup = find("_mockup.png");
    const featured = find("_featured.png"); // made by the Print Agent
    const markerName = stamp + "_shopify.json";
    // the WebP copies that go to Shopify
    const names = { featured: stamp + "_featured.webp", mockup: stamp + "_mockup.webp" };
    const inDrive = Object.fromEntries(Object.entries(names).map(([key, name]) => [key, files.some((f) => f.name === name)]));
    if (!product || !mockup || !featured || find("_shopify.json")) return;
    const tries = files.filter((f) => f.name.startsWith("_upload-try-")).length;
    if (tries >= maxTries || files.some((f) => f.name === "_upload-gave-up")) return;
    pending.push({ json: { folderId: folder.id, folder: folder.name, stamp, productId: product.id, artworkId: art.id, artworkName: art.name, mockupId: mockup.id, mockupName: mockup.name, featuredId: featured.id, names, inDrive, markerName, tries } });
});
pending.sort((a, b) => a.json.tries - b.json.tries || Number(a.json.folder) - Number(b.json.folder));
const todo = pending.slice(0, Number(settings.maxPerRun) || 10);
return todo.length ? todo : [{ json: { none: true } }];

// Folders tried maxTries times that still have no <folder>_shopify.json and no "_upload-gave-up" marker yet
const settings = $('upload: Settings').first().json;
const maxTries = Number(settings.maxTries) || 3;
const folders = $('upload: Folders').all();
const out = [];
$input.all().forEach((item, i) => {
    const folder = folders[i].json;
    if (folder.none) return;
    const files = item.json.files || [];
    const art = files.find((f) => /^.+_art\.png$/.test(f.name));
    if (!art || files.some((f) => f.name === art.name.slice(0, -"_art.png".length) + "_shopify.json")) return;
    const tries = files.filter((f) => f.name.startsWith("_upload-try-")).length;
    if (tries >= maxTries && !files.some((f) => f.name === "_upload-gave-up")) out.push({ json: { folderId: folder.id, folder: folder.name, tries } });
});
return out.length ? out : [{ json: { none: true } }];

const settings = $('upload: Settings').first().json;
const up = $('upload: Given up folders').all().map((item) => item.json).filter((f) => !f.none);
if (!up.length || !String(settings.telegramChatId || "").trim()) return [];
return [{ json: { text: ["Shopify Uploader: gave up on folder" + (up.length === 1 ? " " : "s ") + up.map((f) => f.folder).join(", ") + " after " + settings.maxTries + " tries (no Shopify draft).", "", "The error is in the Error Handler's alerts. To try again, delete the files named _upload-... in the folder."].join("\n") } }];

