parameters.jsCode:
// What this run uploaded (visible in the execution log)
const products = $input.all().map((item) => item.json).filter((p) => p.folder);
return [{ json: { uploaded: products.length, products } }];

const settings = $('upload: Settings').first().json;
if (!String(settings.telegramChatId || "").trim()) return [];
const products = $input.first().json.products || [];
if (!products.length) return [];
const lines = ["Shopify Uploader: " + products.length + " draft" + (products.length === 1 ? "" : "s") + " created"];
for (const p of products.sort((a, b) => Number(a.folder) - Number(b.folder))) {
    lines.push("- " + p.folder + " " + p.title + (p.variants ? ", " + p.variants + " variants" : "") + (p.onlineStore === "published" ? ", on the Online Store" : ", NOT on the Online Store (" + String(p.onlineStore || "").replace(/^not published: /, "") + ")"));
    lines.push("  " + p.adminUrl);
}
lines.push("", "Review each draft and set it to Active to put it on sale.");
return [{ json: { text: lines.join("\n").slice(0, 4000) } }];

// My lock, plus locks left behind by crashed runs
const processed = $('upload: Summary').isExecuted && $('upload: Summary').first().json.uploaded > 0;
const ids = [$('upload: Won the lock?').first().json.lockId, ...$('upload: Lock state').first().json.stale];
return ids.map((id) => ({ json: { id, processed: !!processed } }));

// One item per painted folder of each batch, to look at its files (a batch with no folder gets one empty item)
const listed = $('upload: Painted batches').all();
const out = [];
$input.all().forEach((item, i) => {
    const manifest = item.json;
    if (!manifest || !Array.isArray(manifest.files) || manifest.notified === true) return;
    const base = { manifestId: listed[i].json.manifestId, batchId: manifest.batchId };
    const done = manifest.files.filter((e) => e.status === "done" && e.folderId);
    if (!done.length) out.push({ json: { ...base, folderId: "", folder: "" } });
    for (const entry of done) out.push({ json: { ...base, folderId: entry.folderId, folder: entry.folder } });
});
return out;

// A batch is complete when every painted folder has its <folder>_shopify.json; stuck when it is still not
// complete batchStuckHours after it was painted (announced once, then again when it completes)
const settings = $('upload: Settings').first().json;
const folders = $('upload: Batch folders').all();
const manifests = {};
$('upload: Download batch manifests').all().forEach((item, i) => { manifests[$('upload: Painted batches').all()[i].json.manifestId] = item.json; });
const batches = {};
$input.all().forEach((item, i) => {
    const f = folders[i].json;
    const batch = (batches[f.manifestId] = batches[f.manifestId] || { manifestId: f.manifestId, batchId: f.batchId, markers: [], missing: [] });
    if (!f.folderId) return;
    const names = (item.json.files || []).map((x) => x.name);
    const marker = (item.json.files || []).find((x) => /_shopify\.json$/.test(x.name));
    if (marker) { batch.markers.push({ folder: f.folder, fileId: marker.id }); return; }
    const lacks = [];
    if (!names.some((n) => /_product\.json$/.test(n))) lacks.push("product JSON");
    if (!names.some((n) => /_mockup\.png$/.test(n))) lacks.push("mockup");
    lacks.push("Shopify draft");
    batch.missing.push({ folder: f.folder, lacks });
});
const out = [];
for (const batch of Object.values(batches)) {
    const manifest = manifests[batch.manifestId];
    const hours = (Date.now() - new Date(manifest.paintedAt || manifest.submittedAt).getTime()) / 3600000;
    const complete = batch.missing.length === 0;
    const stuck = !complete && hours >= Number(settings.batchStuckHours) && manifest.notified !== "stuck";
    if (complete || stuck) out.push({ json: { ...batch, kind: complete ? "complete" : "stuck" } });
}
return out;

// The Shopify markers of the batches to announce (their admin links); one placeholder when there is none
const out = [];
for (const item of $input.all()) for (const m of item.json.markers) out.push({ json: { batchId: item.json.batchId, folder: m.folder, fileId: m.fileId } });
return out.length ? out : [{ json: { placeholder: true } }];

// One Telegram message per batch, and its manifest marked as announced
const settings = $('upload: Settings').first().json;
const toRead = $('upload: Markers to read').all();
const links = {};
$input.all().forEach((item, i) => {
    const m = toRead[i].json;
    if (m.placeholder) return;
    (links[m.batchId] = links[m.batchId] || []).push({ folder: m.folder, title: item.json.title || "", url: item.json.adminUrl || "" });
});
const manifests = {};
$('upload: Download batch manifests').all().forEach((item, i) => { manifests[$('upload: Painted batches').all()[i].json.manifestId] = item.json; });
return $('upload: Batch status').all().map((item) => {
    const batch = item.json;
    const manifest = JSON.parse(JSON.stringify(manifests[batch.manifestId]));
    const drafts = (links[batch.batchId] || []).sort((a, b) => Number(a.folder) - Number(b.folder));
    const failed = manifest.files.filter((e) => e.status === "failed");
    const refused = manifest.refused || [];
    const lines = [];
    if (batch.kind === "complete") {
        lines.push("Artwork batch " + batch.batchId + ": " + drafts.length + " draft" + (drafts.length === 1 ? "" : "s") + " ready in Shopify");
    } else {
        lines.push("Artwork batch " + batch.batchId + " is still not all in Shopify after " + settings.batchStuckHours + " h");
        for (const m of batch.missing) lines.push("- " + m.folder + " is missing: " + m.lacks.join(", "));
        if (drafts.length) lines.push("", "Ready so far:");
    }
    for (const d of drafts) lines.push("- " + d.folder + (d.title ? " " + d.title : "") + (d.url ? ": " + d.url : ""));
    if (failed.length) {
        lines.push("", failed.length + " not painted:");
        for (const e of failed) lines.push("- " + e.originalName + ": " + (e.reason || "failed"));
    }
    if (refused.length) {
        lines.push("", refused.length + " refused at upload:");
        for (const r of refused) lines.push("- " + r.name + ": " + r.reason);
    }
    manifest.notified = batch.kind === "complete" ? true : "stuck";
    manifest.notifiedAt = $now.setZone("Africa/Casablanca").toISO();
    return {
        json: { manifestId: batch.manifestId, batchId: batch.batchId, kind: batch.kind, text: lines.join("\n").slice(0, 4000), rename: batch.kind === "complete" ? batch.batchId + "_batch_sent.json" : "" },
        binary: { manifest: { data: Buffer.from(JSON.stringify(manifest, null, 2)).toString("base64"), mimeType: "application/json", fileName: batch.batchId + "_batch.json" } },
    };
});

// The batches whose message went out, with their updated manifest
return $input.all().map((item, i) => {
    const sent = $('upload: Batch messages').itemMatching(i);
    return { json: sent.json, binary: sent.binary };
});

// Another run holds a fresh lock (refreshed within its stale time, kept in its description)
const OWN = 5;
const staleMs = (l) => { const m = /staleMinutes=(\d+)/.exec(l.description || ""); return (m ? Number(m[1]) : OWN) * 60000; };
const isFresh = (l) => Date.now() - new Date(l.modifiedTime || l.createdTime).getTime() < staleMs(l);
const locks = $input.first().json.files || [];
const fresh = locks.filter(isFresh);
const stale = locks.filter((l) => !fresh.includes(l)).map((l) => l.id);
return [{ json: { free: fresh.length === 0, fresh: fresh.length, stale } }];

// Two runs can create a lock at the same moment: the oldest fresh lock wins, the other run steps back
const mine = $('prices: Create lock').last().json;
const OWN = 5;
const staleMs = (l) => { const m = /staleMinutes=(\d+)/.exec(l.description || ""); return (m ? Number(m[1]) : OWN) * 60000; };
const isFresh = (l) => Date.now() - new Date(l.modifiedTime || l.createdTime).getTime() < staleMs(l);
const fresh = ($input.first().json.files || [])
    .filter((l) => l.id === mine.id || isFresh(l))
    .sort((a, b) => (a.createdTime < b.createdTime ? -1 : a.createdTime > b.createdTime ? 1 : a.id < b.id ? -1 : 1));
return [{ json: { won: fresh.length > 0 && fresh[0].id === mine.id, lockId: mine.id } }];

const file = $input.first().json;
if (!file.id || file.trashed) throw new Error("The prices sheet (pricesSheetId in Settings) is missing or in the trash");
if (file.mimeType !== "application/vnd.google-apps.spreadsheet") throw new Error(file.name + " is not a Google Sheet: pricesSheetId must point to the prices spreadsheet");
return [{ json: { id: file.id, name: file.name, modifiedTime: file.modifiedTime } }];

// The CSV becomes the product's options and variants: Size / Canvas Type / Colors, like the store's other kits.
// A price of 0 means "not sold": no variant for that combination (the product page shows it greyed out).
const settings = $('prices: Settings').first().json;
const file = $('prices: Prices file').first().json;
const text = String($input.first().json.data || "").replace(/^\uFEFF/, "");
// empty rows of the sheet export as ",,," lines
const lines = text.split(/\r?\n/).map((l) => l.trim()).filter((l) => l.replace(/[,;"\s]/g, ""));
// one CSV line into cells; a quoted cell may hold a comma (e.g. "179,00" in a French-format sheet)
const split = (line) => {
    const cells = [];
    let cell = "";
    let quoted = false;
    for (let i = 0; i < line.length; i++) {
        const ch = line[i];
        if (quoted) {
            if (ch === '"' && line[i + 1] === '"') { cell += '"'; i++; }
            else if (ch === '"') quoted = false;
            else cell += ch;
        } else if (ch === '"') quoted = true;
        else if (ch === "," || ch === ";") { cells.push(cell.trim()); cell = ""; }
        else cell += ch;
    }
    cells.push(cell.trim());
    return cells;
};
const header = split(lines.shift() || "").map((h) => h.toLowerCase().replace(/\s+/g, "_"));
const col = (name) => header.indexOf(name);
for (const name of ["canvas_type", "size", "colors", "price"]) {
    if (col(name) < 0) throw new Error(file.name + ": missing column " + name + " (columns: canvas_type,size,colors,price)");
}
// "179", "179.00", "179,00" or "179,00 MAD"; an empty price cell counts as 0 (not sold)
const money = (value) => Number(String(value).replace(/[^\d,.-]/g, "").replace(",", ".") || "0");
const normSize = (value) => String(value || "").toLowerCase().trim().replace(/\s*cm$/, "").replace(/\s*[x×]\s*/, "x");
const soldSizes = String(settings.sizes || "").split(",").map(normSize).filter(Boolean);
const rows = [];
const seen = new Set();
lines.forEach((line, i) => {
    const cells = split(line);
    const size = normSize(cells[col("size")]);
    if (soldSizes.length && !soldSizes.includes(size)) return; // not a size the store sells
    let canvasType = cells[col("canvas_type")];
    if (!/canvas$/i.test(canvasType)) canvasType += " Canvas"; // "Rolled" -> "Rolled Canvas", the store's wording
    const colors = String(parseInt(cells[col("colors")], 10));
    const price = money(cells[col("price")]);
    const compareCell = col("compare_at_price") >= 0 ? cells[col("compare_at_price")] : "";
    const compareAt = compareCell ? money(compareCell) : price * Number(settings.compareAtMultiplier || 0);
    const where = file.name + " line " + (i + 2);
    if (!/^\d+(?:[.]\d+)?x\d+(?:[.]\d+)?$/.test(size)) throw new Error(where + ": size must look like 30x40");
    if (colors !== "18") throw new Error(where + ": Kids prices must use 18 colors");
    if (colors === "NaN") throw new Error(where + ": colors must be a number");
    if (!(price >= 0)) throw new Error(where + ": price must be a number (0 = not sold)");
    const key = size + "|" + canvasType + "|" + colors;
    if (seen.has(key)) throw new Error(where + ": " + key.replace(/\|/g, " / ") + " is listed twice");
    seen.add(key);
    const sold = price > 0;
    rows.push({ key, size, canvasType, colors, sold, price: price.toFixed(2), compareAtPrice: sold && compareAt > price ? compareAt.toFixed(2) : null });
});
if (!rows.length) throw new Error(file.name + " has no prices" + (soldSizes.length ? " for the sizes in Settings (" + soldSizes.join(", ") + ")" : ""));
const missing = soldSizes.filter((s) => !rows.some((r) => r.size === s));
if (missing.length) throw new Error(file.name + " has no prices for " + missing.join(", ") + " (sizes in Settings; a price of 0 marks a combination not sold)");
const soldRows = rows.filter((r) => r.sold);
if (!soldRows.length) throw new Error(file.name + ": every price is 0, a product needs at least one combination for sale");
if (soldRows.length > 100) throw new Error(file.name + ": Shopify allows 100 variants per product, the sheet has " + soldRows.length + " prices above 0");

const area = (s) => s.split("x").reduce((a, b) => a * Number(b), 1);
const unique = (values) => [...new Set(values)];
const order = (list) => {
    const sizes = unique(list.map((r) => r.size)).sort((a, b) => area(a) - area(b));
    const canvasTypes = unique(list.map((r) => r.canvasType)).sort();
    const colors = unique(list.map((r) => r.colors)).sort((a, b) => a - b);
    list.sort((a, b) => sizes.indexOf(a.size) - sizes.indexOf(b.size) || canvasTypes.indexOf(a.canvasType) - canvasTypes.indexOf(b.canvasType) || a.colors - b.colors);
    return { sizes, canvasTypes, colors };
};
order(rows);
// the options list only the values that have a combination for sale (Shopify has no option value without a variant)
const values = order(soldRows);
const productOptions = [
    { name: "Size", position: 1, values: values.sizes.map((name) => ({ name })) },
    { name: "Canvas Type", position: 2, values: values.canvasTypes.map((name) => ({ name })) },
    { name: "Colors", position: 3, values: values.colors.map((name) => ({ name })) },
];
const variants = soldRows.map((r, i) => ({
    optionValues: [
        { optionName: "Size", name: r.size },
        { optionName: "Canvas Type", name: r.canvasType },
        { optionName: "Colors", name: r.colors },
    ],
    price: r.price,
    compareAtPrice: r.compareAtPrice,
    position: i + 1,
    inventoryPolicy: "DENY",
    inventoryItem: { tracked: false, requiresShipping: true },
}));
return [{ json: { pricesVersion: file.modifiedTime, variantCount: variants.length, notSold: rows.length - soldRows.length, productOptions, variants, rows } }];

// First page, or the next one after the last page read
if ($runIndex === 0) return [{ json: { cursor: null, products: [] } }];
const last = $('prices: Collect products').first().json;
return [{ json: { cursor: last.cursor, products: last.products } }];

parameters.jsonBody:
={{ JSON.stringify({
    query: "query Page($after: String) { products(first: 10, after: $after, query: \"product_type:'Paint by Numbers Kit' AND tag:kids-kits\") { pageInfo { hasNextPage endCursor } nodes { id title handle tags options { name position optionValues { id name fr: translations(locale: \"fr\") { key value } ar: translations(locale: \"ar\") { key value } } } variants(first: 60) { nodes { id sku price compareAtPrice selectedOptions { name value } } } } } }",
    variables: { after: $json.cursor }
}) }}

parameters.jsCode:
// The Uploader's products only: handle "<name>-<folder>" and every SKU starting with the folder number
const previous = $('prices: Next page').first().json.products;
const response = $input.first().json;
if (response.errors) throw new Error("Shopify: " + JSON.stringify(response.errors).slice(0, 300));
const page = response.data.products;
const mine = page.nodes.filter((p) => {
    // Kids are owned by the independent Kids workflow.
    if (!(p.tags || []).includes("kids-kits")) return false;
    if (!p.variants.nodes.every((v) => v.selectedOptions.some((o) => o.name === "Colors" && o.value === "18") && v.selectedOptions.some((o) => o.name === "Size" && o.value === "24x30"))) return false;
    const m = /-(\d{4,})$/.exec(p.handle);
    return m && p.variants.nodes.length && p.variants.nodes.every((v) => new RegExp("^" + m[1] + "\\d+[RS]$").test(v.sku || ""));
}).map((p) => ({ ...p, folder: /-(\d{4,})$/.exec(p.handle)[1] }));
return [{ json: { cursor: page.pageInfo.endCursor, more: page.pageInfo.hasNextPage, products: previous.concat(mine) } }];

// Canvas option values without their French / Arabic name (from canvasTranslations in Settings)
const wanted = JSON.parse($('prices: Settings').first().json.canvasTranslations || "{}");
const todo = [];
for (const p of $input.first().json.products) {
    for (const opt of p.options) {
        if (opt.name !== "Canvas Type") continue;
        for (const v of opt.optionValues) {
            const want = wanted[v.name];
            if (!want) continue;
            const have = { fr: ((v.fr || [])[0] || {}).value, ar: ((v.ar || [])[0] || {}).value };
            const locales = Object.keys(want).filter((l) => have[l] !== want[l]);
            if (locales.length) todo.push({ id: v.id, name: v.name, folder: p.folder, translations: locales.map((l) => ({ locale: l, value: want[l] })) });
        }
    }
}
return [{ json: { todo, ids: todo.map((t) => t.id) } }];

parameters.jsonBody:
={{ JSON.stringify({
    query: "query D($ids: [ID!]!) { translatableResourcesByIds(first: 100, resourceIds: $ids) { nodes { resourceId translatableContent { key digest } } } }",
    variables: { ids: $json.ids.slice(0, 100) }
}) }}

parameters.jsCode:
// One request registering every missing name (a value's digest proves which English text it translates)
const todo = $('prices: Missing translations').first().json.todo;
const nodes = ((($input.first().json.data || {}).translatableResourcesByIds) || {}).nodes || [];
const vars = [];
const parts = [];
const variables = {};
todo.forEach((t, i) => {
    const node = nodes.find((n) => n.resourceId === t.id);
    const digest = node && (node.translatableContent.find((c) => c.key === "name") || {}).digest;
    if (!digest) return;
    vars.push("$r" + i + ": ID!", "$t" + i + ": [TranslationInput!]!");
    parts.push("t" + i + ": translationsRegister(resourceId: $r" + i + ", translations: $t" + i + ") { userErrors { field message } }");
    variables["r" + i] = t.id;
    variables["t" + i] = t.translations.map((x) => ({ locale: x.locale, key: "name", value: x.value, translatableContentDigest: digest }));
});
if (!parts.length) return [{ json: { none: true } }];
return [{ json: { count: parts.length, body: { query: "mutation R(" + vars.join(", ") + ") { " + parts.join(" ") + " }", variables } } }];

// Per product: variants to update (price), delete (price 0 in the sheet) and create (price above 0 again)
const prices = $('prices: Prices').first().json;
const products = $('prices: Collect products').first().json.products;
const byKey = {};
for (const row of prices.rows) byKey[row.key] = row;
const optionOf = (v, name) => (v.selectedOptions.find((o) => o.name === name) || {}).value;
const keyOf = (v) => optionOf(v, "Size") + "|" + optionOf(v, "Canvas Type") + "|" + optionOf(v, "Colors");
const money = (x) => (x === null || x === undefined || x === "" ? null : Number(x).toFixed(2));
// a product tagged "sale-<percent>" (e.g. sale-50) shows a compare-at ("before") price that makes that discount:
// price / (1 - percent), rounded to a whole number (249 with sale-50 -> 498). Without the tag: the sheet's value
// (compare_at_price column, or price x compareAtMultiplier), none when both are empty/0.
const saleOf = (p) => { for (const t of p.tags || []) { const m = /^sale-(\d{1,2})$/i.exec(String(t).trim()); if (m && Number(m[1]) > 0) return Number(m[1]); } return 0; };
const compareFor = (row, sale) => (sale ? Math.round(Number(row.price) / (1 - sale / 100)).toFixed(2) : row.compareAtPrice);
const out = [];
for (const p of products) {
    const sale = saleOf(p);
    const existing = {};
    for (const v of p.variants.nodes) existing[keyOf(v)] = v;
    const update = [];
    const remove = [];
    const create = [];
    for (const [key, v] of Object.entries(existing)) {
        const row = byKey[key];
        if (!row) continue; // not in the sheet (another size...): left alone
        if (!row.sold) { remove.push({ id: v.id, key }); continue; }
        const compareAtPrice = compareFor(row, sale);
        if (money(v.price) !== row.price || money(v.compareAtPrice) !== compareAtPrice) {
            update.push({ id: v.id, price: row.price, compareAtPrice, key, was: money(v.price), wasBefore: money(v.compareAtPrice) });
        }
    }
    for (const row of prices.rows) {
        if (!row.sold || existing[row.key]) continue;
        create.push({
            optionValues: [{ optionName: "Size", name: row.size }, { optionName: "Canvas Type", name: row.canvasType }, { optionName: "Colors", name: row.colors }],
            price: row.price,
            compareAtPrice: compareFor(row, sale),
            inventoryPolicy: "DENY",
            inventoryItem: { tracked: false, requiresShipping: true, sku: p.folder + row.size.replace(/[^0-9]/g, "") + row.colors + row.canvasType.charAt(0).toUpperCase() },
        });
    }
    if (!update.length && !remove.length && !create.length) continue;
    // a product always keeps at least one variant: if the sheet would leave none, nothing is deleted
    const kept = Object.keys(existing).length - remove.length + create.length;
    const removeNow = kept > 0 ? remove : [];
    // new values go back to their place: options in the sheet's order, only the values the product will have
    const after = new Set(Object.keys(existing).filter((k) => !removeNow.some((r) => r.key === k)).concat(create.map((c) => c.optionValues.map((o) => o.name).join("|"))));
    const valuesOf = (i) => [...new Set(prices.rows.map((r) => r.key.split("|")[i]))].filter((value) => [...after].some((k) => k.split("|")[i] === value)).map((name) => ({ name }));
    const reorder = create.length ? [{ name: "Size", values: valuesOf(0) }, { name: "Canvas Type", values: valuesOf(1) }, { name: "Colors", values: valuesOf(2) }] : [];
    const vars = [];
    const parts = [];
    if (create.length) { vars.push("$c: [ProductVariantsBulkInput!]!"); parts.push("c: productVariantsBulkCreate(productId: $p, variants: $c) { userErrors { field message } }"); }
    if (update.length) { vars.push("$u: [ProductVariantsBulkInput!]!"); parts.push("u: productVariantsBulkUpdate(productId: $p, variants: $u) { userErrors { field message } }"); }
    if (removeNow.length) { vars.push("$d: [ID!]!"); parts.push("d: productVariantsBulkDelete(productId: $p, variantsIds: $d) { userErrors { field message } }"); }
    if (reorder.length) { vars.push("$o: [OptionReorderInput!]!"); parts.push("o: productOptionsReorder(productId: $p, options: $o) { userErrors { field message } }"); }
    out.push({ json: {
        productId: p.id,
        folder: p.folder,
        title: p.title,
        sale,
        summary: { updated: update.map((u) => u.key + " " + u.was + " -> " + u.price + (u.wasBefore !== u.compareAtPrice ? " (before-price " + (u.wasBefore || "none") + " -> " + (u.compareAtPrice || "none") + ")" : "")), removed: removeNow.map((r) => r.key), created: create.map((c) => c.optionValues.map((o) => o.name).join("|")), keptAll: remove.length !== removeNow.length },
        body: {
            query: "mutation Sync($p: ID!" + (vars.length ? ", " + vars.join(", ") : "") + ") { " + parts.join(" ") + " }",
            variables: { p: p.id, c: create, u: update.map((u) => ({ id: u.id, price: u.price, compareAtPrice: u.compareAtPrice })), d: removeNow.map((r) => r.id), o: reorder },
        },
    } });
}
return out.length ? out : [{ json: { none: true, checked: products.length } }];

// One message: what changed per product, and any error Shopify returned
const changes = $('prices: Changes').all().map((item) => item.json);
const answers = $input.all().map((item) => item.json);
const lines = [];
let failed = 0;
changes.forEach((c, i) => {
    const a = answers[i] || {};
    const errors = [];
    if (a.error) errors.push(String(a.error.message || a.error));
    for (const e of a.errors || []) errors.push(e.message);
    for (const part of Object.values(a.data || {})) for (const e of (part && part.userErrors) || []) errors.push(e.message);
    const s = c.summary;
    const bits = [];
    if (s.updated.length) bits.push(s.updated.length + " price" + (s.updated.length === 1 ? "" : "s") + " updated");
    if (s.removed.length) bits.push(s.removed.length + " not sold (removed)");
    if (s.created.length) bits.push(s.created.length + " back on sale");
    if (s.keptAll) bits.push("nothing removed: every price of this product is 0 in the sheet");
    lines.push("- " + c.folder + " " + c.title + ": " + bits.join(", ") + (errors.length ? " | ERROR: " + errors.join("; ").slice(0, 300) : ""));
    if (errors.length) failed++;
});
const tr = $('prices: Save translations').isExecuted ? $('prices: Save translations').first().json : null;
if (tr) {
    const errs = [];
    if (tr.error) errs.push(String(tr.error.message || tr.error));
    for (const e of tr.errors || []) errs.push(e.message);
    for (const part of Object.values(tr.data || {})) for (const e of (part && part.userErrors) || []) errs.push(e.message);
    if (errs.length) { lines.push("- translations: ERROR " + errs.join("; ").slice(0, 300)); failed++; }
}
const head = "Price Sync: " + changes.length + " product" + (changes.length === 1 ? "" : "s") + " brought in line with the prices sheet" + (failed ? ", " + failed + " with errors (retried next hour)" : "");
return [{ json: { failed, text: [head, ...lines].join("\n").slice(0, 4000) } }];

// My lock, plus locks left behind by crashed runs
const processed = false;
const ids = [$('prices: Won the lock?').first().json.lockId, ...$('prices: Lock state').first().json.stale];
return ids.map((id) => ({ json: { id, processed: !!processed } }));

// Another run holds a fresh lock (refreshed within its stale time, kept in its description)
const OWN = 15;
const staleMs = (l) => { const m = /staleMinutes=(\d+)/.exec(l.description || ""); return (m ? Number(m[1]) : OWN) * 60000; };
const isFresh = (l) => Date.now() - new Date(l.modifiedTime || l.createdTime).getTime() < staleMs(l);
const locks = $input.first().json.files || [];
const fresh = locks.filter(isFresh);
const stale = locks.filter((l) => !fresh.includes(l)).map((l) => l.id);
return [{ json: { free: fresh.length === 0, fresh: fresh.length, stale } }];

// Two runs can create a lock at the same moment: the oldest fresh lock wins, the other run steps back
const mine = $('translate: Create lock').last().json;
const OWN = 15;
const staleMs = (l) => { const m = /staleMinutes=(\d+)/.exec(l.description || ""); return (m ? Number(m[1]) : OWN) * 60000; };
const isFresh = (l) => Date.now() - new Date(l.modifiedTime || l.createdTime).getTime() < staleMs(l);
const fresh = ($input.first().json.files || [])
    .filter((l) => l.id === mine.id || isFresh(l))
    .sort((a, b) => (a.createdTime < b.createdTime ? -1 : a.createdTime > b.createdTime ? 1 : a.id < b.id ? -1 : 1));
return [{ json: { won: fresh.length > 0 && fresh[0].id === mine.id, lockId: mine.id } }];

// First page, or the next one after the last page read
if ($runIndex === 0) return [{ json: { cursor: null, products: [], givenUp: 0 } }];
const last = $('translate: Collect products').first().json;
return [{ json: { cursor: last.cursor, products: last.products, givenUp: last.givenUp } }];

