}) }}

parameters.jsCode:
// My lock, plus locks left behind by crashed runs
const processed = $('translate: Products to translate').isExecuted && $('translate: Products to translate').first().json.waiting > 0 && $('translate: Translation report').isExecuted && $('translate: Translation report').first().json.done > 0;
const ids = [$('translate: Won the lock?').first().json.lockId, ...$('translate: Lock state').first().json.stale];
return ids.map((id) => ({ json: { id, processed: !!processed } }));

const input = $input.first().json;
const mode = (input.body || input).mode || "maintenance";
const allowed = ["worker", "titling", "print", "upload", "prices", "translate", "batch-messages"];
if (mode !== "maintenance" && !allowed.includes(mode)) throw new Error("Unknown Kids stage: " + mode);
return [{ json: { mode } }];
